# Set a specific run ID to inspect (8-char hex)
RUN_ID = ""  # e.g. "a1b2c3d4" — leave empty to skip

if RUN_ID:
    result = subprocess.run([PYTHON, CLI, "--run-id", RUN_ID, "--verbose"], capture_output=True, text=True)
    print(result.stdout)
    if result.stderr:
        print("STDERR:", result.stderr[-2000:])
else:
    print("Set RUN_ID above to analyze a specific run.")

# List result files
results_dir = project_root / "results"

if results_dir.exists():
    print("Result directories:")
    for d in sorted(results_dir.iterdir()):
        if d.is_dir():
            print(f"  {d.name}/")
            for f in d.iterdir():
                print(f"    - {f.name}")
else:
    print("No results directory yet. Run an experiment first!")

# View conversation.md from most recent result
if results_dir.exists():
    latest = sorted(results_dir.iterdir())[-1] if list(results_dir.iterdir()) else None
    if latest:
        conv_file = latest / "conversation.md"
        if conv_file.exists():
            print(f"=== {conv_file} ===")
            print(conv_file.read_text())

